<section class="container page-heading"><span class="section-kicker">Akses dan identitas</span><h1>Kelola pengguna</h1><p>Buat akun operasional, ubah informasi kontak, dan nonaktifkan akun tanpa menghapus riwayat transaksi yang terkait.</p></section>
<section class="container admin-page"><div class="row g-4 align-items-start"><div class="col-lg-4"><div class="surface surface-pad"><h2 class="h5 mb-4">Buat akun baru</h2><form method="post" action="<?= e(url('admin-users')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="create"><div class="mb-3"><label class="form-label" for="nama">Nama lengkap</label><input class="form-control" name="nama" id="nama" required maxlength="100"></div><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" name="email" id="email" type="email" required maxlength="100"></div><div class="mb-3"><label class="form-label" for="no_telepon">Nomor telepon</label><input class="form-control" name="no_telepon" id="no_telepon" maxlength="20"></div><div class="mb-3"><label class="form-label" for="username">Username</label><input class="form-control" name="username" id="username" required minlength="3" maxlength="50"></div><div class="mb-3"><label class="form-label" for="password">Kata sandi awal</label><input class="form-control" name="password" id="password" type="password" required minlength="8"></div><div class="mb-4"><label class="form-label" for="peran">Peran</label><select class="form-select" name="peran" id="peran"><option value="fotografer">Fotografer</option><option value="pelanggan">Pelanggan</option></select><div class="form-note mt-2">Akun admin baru tidak dibuat melalui formulir ini.</div></div><button class="btn btn-copper w-100" type="submit">Buat Akun</button></form></div></div><div class="col-lg-8"><div class="surface"><div class="surface-pad"><h2 class="h5 mb-1">Semua pengguna</h2><p class="form-note mb-0">Peran akun admin tidak dapat dinonaktifkan dari halaman ini.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Pengguna</th><th>Peran</th><th>Aktif</th><th>Ubah data</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['nama']) ?></strong><span class="subtext"><?= e($u['email']) ?> · @<?= e($u['username']) ?></span></td><td><?= e(ucfirst($u['peran'])) ?></td><td><span class="badge-status <?= $u['aktif']?'success':'secondary' ?>"><?= $u['aktif']?'Aktif':'Nonaktif' ?></span></td><td><form method="post" action="<?= e(url('admin-users')) ?>" class="d-flex flex-column gap-1" style="min-width:170px"><?= csrf_field() ?><input type="hidden" name="action" value="edit"><input type="hidden" name="id_pengguna" value="<?= (int)$u['id_pengguna'] ?>"><input class="form-control form-control-sm" name="nama" maxlength="100" required value="<?= e($u['nama']) ?>" aria-label="Nama pengguna"><input class="form-control form-control-sm" name="no_telepon" maxlength="20" value="<?= e($u['no_telepon']) ?>" aria-label="Nomor telepon"><button class="btn btn-sm btn-outline-dark" type="submit">Simpan</button></form></td><td><?php if($u['peran']!=='admin'): ?><form method="post" action="<?= e(url('admin-users')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id_pengguna" value="<?= (int)$u['id_pengguna'] ?>"><input type="hidden" name="active" value="<?= $u['aktif']?'0':'1' ?>"><button class="btn btn-sm <?= $u['aktif']?'btn-outline-danger':'btn-outline-success' ?>" data-confirm="<?= $u['aktif']?'Nonaktifkan':'Aktifkan' ?> akun <?= e($u['nama']) ?>?" type="submit"><?= $u['aktif']?'Nonaktifkan':'Aktifkan' ?></button></form><?php else: ?><span class="muted small">Dilindungi</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></section>
